    // only some are drawn, each with the light of those left out, so the sum stays the same.
    // A new choice each pass, so a developed image converges on every disc.
    let keep = min(1.0, BLUR_BUDGET / (PI * (rad.x / perPx.x) * (rad.y / perPx.y)));
