  // pixel size, or a disc out of focus) gives only the light, or the coverage, its true size
  // holds, so brightness does not depend on screen size, distance or focus.
  let cover = clamp((r * u.proj.x) / max(rad.x, 1e-12), 0.0, 1.0);
